VALUES

('KLH/OUT/2026/0001', '2026-07-16', 'कार्यकारी अभियंता, महावितरण', 'कार्यकारी अभियंता', 11, 'सांगवडे गावातील वीज खंडन समस्येबाबत तातडीने उपाययोजना करणेबाबत.', 'महोदय, कोल्हापूर दक्षिण मतदारसंघातील सांगवडे गावातील ग्रामस्थांनी सादर केलेल्या निवेदनानुसार गावात वारंवार वीज पुरवठा खंडित होत आहे. तरी तातडीने योग्य ती दुरुस्ती करून नियमित वीज पुरवठा सुरू करावा.', NULL, 4, 1, NULL, 1, 2, '2026-07-16 10:30:00', '2026-07-16 10:30:00'),
('KLH/OUT/2026/0002', '2026-07-17', 'तहसीलदार, करवीर', 'तहसीलदार', 2, 'नेर्ली येथील शेतजमिनीचे ७/१२ उतारे वेळेवर मिळणेबाबत.', 'महोदय, नेर्ली गावातील शेतकरी श्री. संतोष दादा पाटील यांनी सादर केलेल्या निवेदनानुसार जमिनीचा सातबारा उतारा मिळण्यास विलंब होत आहे. त्वरित कारवाई करून ७/१२ उतारा देण्यात यावा.', NULL, 5, 1, NULL, 1, 2, '2026-07-17 11:00:00', '2026-07-17 11:00:00'),
('KLH/OUT/2026/0003', '2026-07-18', 'शिक्षणाधिकारी (प्राथमिक), जि.प. कोल्हापूर', 'शिक्षणाधिकारी', 13, 'पाचगाव जिल्हा परिषद शाळेत शिक्षकांची नियुक्ती करणेबाबत.', 'महोदय, पाचगाव जि.प. शाळेत वर्ग ५ ते ७ साठी शिक्षक उपलब्ध नसल्यामुळे विद्यार्थ्यांचे शैक्षणिक नुकसान होत आहे. तात्पुरत्या किंवा कायमस्वरूपी शिक्षकांची नियुक्ती करावी.', NULL, 6, 0, NULL, 1, 2, '2026-07-18 14:00:00', '2026-07-18 14:00:00'),
('KLH/OUT/2026/0004', '2026-07-19', 'जिल्हा समाजकल्याण अधिकारी, कोल्हापूर', 'जिल्हा समाजकल्याण अधिकारी', 15, 'वृद्धापकाळ निवृत्तीवेतन थकबाकी जमा करणेबाबत.', 'महोदय, राजेंद्रनगर येथील श्रीमती द्रौपदाबाई कदम यांचे मागील ४ महिन्यांचे वृद्धापकाळ निवृत्तीवेतन खात्यात जमा झाले नाही. कृपया सदर रक्कम तात्काळ मंजूर करून वितरित करावी.', NULL, 7, 1, NULL, 1, 2, '2026-07-19 09:30:00', '2026-07-19 09:30:00'),
('KLH/OUT/2026/0005', '2026-07-20', 'जिल्हा पुरवठा अधिकारी, कोल्हापूर', 'जिल्हा पुरवठा अधिकारी', 8, 'वसगडे येथील नागरिकांचे नवीन रेशनकार्ड मंजूर करणेबाबत.', 'महोदय, वसगडे येथील श्री. गोपाळ शंकर कांबळे यांचा रेशनकार्ड अर्ज प्रलंबित आहे. कुटुंबास धान्याचा लाभ मिळण्यासाठी तातडीने रेशनकार्ड वितरीत करावे.', NULL, 8, 0, NULL, 1, 2, '2026-07-20 10:00:00', '2026-07-20 10:00:00'),
('KLH/OUT/2026/0006', '2026-07-21', 'नोडल अधिकारी, PMAY, कोल्हापूर', 'नोडल अधिकारी', 3, 'प्रधानमंत्री आवास योजना हप्ता वितरणबाबत.', 'महोदय, नंदगाव येथील श्रीमती शांताबाई माने यांच्या अपूर्ण घरासाठी पुढील अनुदानाचा हप्ता तातडीने वर्ग करण्यात यावा.', NULL, 10, 1, NULL, 1, 2, '2026-07-21 11:30:00', '2026-07-21 11:30:00'),
('KLH/OUT/2026/0007', '2026-07-22', 'पोलीस निरीक्षक, स्थानिक पोलीस ठाणे', 'पोलीस निरीक्षक', 16, 'लक्षतीर्थ वसाहत परिसरातील अवैध दारूविक्रीवर कठोर कारवाईबाबत.', 'महोदय, लक्षतीर्थ वसाहतीत उघड्यावर चालणाऱ्या अवैध दारूविक्रीमुळे स्थानिक नागरिक त्रस्त आहेत. परिसरात गस्त वाढवून कडक कारवाई करावी.', NULL, 13, 0, NULL, 1, 2, '2026-07-22 15:00:00', '2026-07-22 15:00:00'),
('KLH/OUT/2026/0008', '2026-07-23', 'गट विकास अधिकारी, करवीर', 'गट विकास अधिकारी', 4, 'तामगाव येथील सामुदायिक शौचालय दुरुस्तीसाठी निधी देण्याबाबत.', 'महोदय, तामगाव येथील बंद असलेले सामुदायिक शौचालय दुरुस्त करून तातडीने वापरायोग्य करावे.', NULL, 14, 1, NULL, 1, 2, '2026-07-23 10:00:00', '2026-07-23 10:00:00'),
('KLH/OUT/2026/0009', '2026-07-24', 'कार्यकारी अभियंता, PWD कोल्हापूर', 'कार्यकारी अभियंता', 9, 'राजारामपुरी मुख्य रस्त्यावरील खड्डे बुजविणेबाबत.', 'महोदय, राजारामपुरी परिसरातील मुख्य रस्त्यावर पडलेले खड्डे पावसाळ्यापूर्वी डांबरीकरणाने बुजवून घ्यावेत.', NULL, 1, 0, NULL, 1, 2, '2026-07-24 11:00:00', '2026-07-24 11:00:00'),
('KLH/OUT/2026/0010', '2026-07-25', 'जिल्हा आरोग्य अधिकारी, कोल्हापूर', 'जिल्हा आरोग्य अधिकारी', 14, 'अवचीतनगर प्राथमिक आरोग्य केंद्रात डॉक्टर नियुक्तीबाबत.', 'महोदय, अवचीतनगर आरोग्य केंद्रात नियमित वैद्यकीय अधिकारी उपस्थित राहतील अशी व्यवस्था करावी.', NULL, 2, 1, NULL, 1, 2, '2026-07-25 12:00:00', '2026-07-25 12:00:00'),
('KLH/OUT/2026/0011', '2026-07-26', 'कार्यकारी अभियंता, जलसंपदा विभाग', 'कार्यकारी अभियंता', 10, 'राधानगरी धरण पाणी साठा व सिंचन आवर्तन पत्र.', 'महोदय, ऑगस्ट महिन्यात शेतीपंपासाठी राधानगरी धरणातून योग्य प्रमाणात सिंचन आवर्तन सोडण्याबाबत मागणी.', NULL, NULL, 0, NULL, 1, 2, '2026-07-26 09:30:00', '2026-07-26 09:30:00'),
('KLH/OUT/2026/0012', '2026-07-27', 'जिल्हा नियोजन अधिकारी, कोल्हापूर', 'जिल्हा नियोजन अधिकारी', 1, '२०२६-२७ जिल्हा नियोजन निधी प्रस्तावांचे शिफारस पत्र.', 'महोदय, कोल्हापूर दक्षिण मतदारसंघातील १० विकासकामांचे प्रस्ताव जिल्हा नियोजन समितीकडे मंजुरीसाठी पाठवत आहे.', NULL, NULL, 1, NULL, 1, 2, '2026-07-27 10:30:00', '2026-07-27 10:30:00'),
('KLH/OUT/2026/0013', '2026-07-28', 'वरिष्ठ अधिकारी, बँक ऑफ महाराष्ट्र', 'शाखा व्यवस्थापक', 3, 'बचत गटांच्या थकीत कर्ज सवलत अर्जाबाबत शिफारस पत्र.', 'महोदय, नेर्ली गावातील महिला बचत गटांना थकीत कर्जावर सवलत व पुनर्गठन देण्याबाबत सकारात्मक विचार व्हावा.', NULL, NULL, 0, NULL, 1, 2, '2026-07-28 11:00:00', '2026-07-28 11:00:00'),
('KLH/OUT/2026/0014', '2026-07-29', 'गट शिक्षण अधिकारी, करवीर', 'गट शिक्षण अधिकारी', 13, 'वडकशिवाले शाळेत डिजिटल संगणक संच पुरविणेबाबत.', 'महोदय, वडकशिवाले जि.प. प्राथमिक शाळेत लोकसहभाग व शासनाच्या योजनेतून संगणक उपलब्ध करून द्यावेत.', NULL, 18, 1, NULL, 1, 2, '2026-07-29 14:00:00', '2026-07-29 14:00:00'),
('KLH/OUT/2026/0015', '2026-07-30', 'जिल्हाधिकारी, कोल्हापूर', 'जिल्हाधिकारी', 1, 'पंचगंगा नदी प्रदूषण व नियंत्रण तातडीची बैठक पत्र.', 'महोदय, पंचगंगा नदीतील प्रदूषण वाढल्याने कोल्हापूर दक्षिण मतदारसंघातील गावांमध्ये पिण्याच्या पाण्याचा प्रश्न गंभीर बनला आहे. यावर तातडीने बैठक आयोजित करावी.', NULL, NULL, 1, NULL, 1, 2, '2026-07-30 16:00:00', '2026-07-30 16:00:00');
